                />
              )
            })}
          </Box>
        </Box>
      ) : (
        <Button
          key="reveal"
          label="Show answer"
          hotkey="s"
          variant="primary"
          autoFocus
          onPress={() => runKey($, { type: 'reveal' }, card)}
        />
      )}
