              <Text color="green">{sparkline(o.reviews7d)}</Text>
              <Text dimColor> 7 days</Text>
            </Text>
          )}
        </Box>
      )
  } else if (sub === 'topics') {
    content = (
      <Box flexDirection="column" gap={1}>
        {section(
          d,
          'improve',
          'Improve',
          i.improve.length === 0 ? (
            <Text dimColor wrap="wrap">
              Nothing weak with 2+ cards. 🎉
            </Text>
          ) : (
            i.improve.map(r => topicRow(d, i, r, `improve-${r.topic}`))
